def log(*a):
    print('[%7.1fs]' % (time.time() - T0), *a, flush=True)


de = lambda p: arb(p[0]) + sym(arb(p[1]))


def mlist(M):
    return [[M[i, j] for j in range(M.ncols())] for i in range(M.nrows())]


def real_mat(M, n=4):
    return arb_mat([[M[i, j].real for j in range(n)] for i in range(n)])


def qr_frame(M, rv):
    n = M.nrows()
    w = [float(rv[j, 0].abs_upper()) + 1e-300 for j in range(n)]
    cols = [[float(M[i, j].mid()) for i in range(n)] for j in range(n)]
    order = sorted(range(n), key=lambda j: -math.sqrt(sum(z*z for z in cols[j]))*w[j])
    Qv = []
    for j in order:
        v = cols[j][:]
        for qv in Qv:
            dd = sum(x*y for x, y in zip(v, qv)); v = [x - dd*y for x, y in zip(v, qv)]
        nv = math.sqrt(sum(z*z for z in v))
        if nv < 1e-280:
            v = [1.0 if i == len(Qv) else 0.0 for i in range(n)]
            for qv in Qv:
                dd = sum(x*y for x, y in zip(v, qv)); v = [x - dd*y for x, y in zip(v, qv)]
            nv = math.sqrt(sum(z*z for z in v))
        Qv.append([z/nv for z in v])
    Qm = arb_mat([[Qv[j][i] for j in range(n)] for i in range(n)])
    return Qm, Qm.inv()


class Lohner:
    def __init__(self, vals):
        n = len(vals)
        self.c = arb_mat([[arb(v.mid())] for v in vals])
        self.B = arb_mat(n, n)
        for i in range(n): self.B[i, i] = 1
        self.r = arb_mat([[v - arb(v.mid())] for v in vals])

    def value(self):
        Y = self.c + self.B*self.r
        return [Y[i, 0] for i in range(Y.nrows())]

    def step(self, P):
        p = P*self.c
        M = P*self.B
        Qm, Qi = qr_frame(M, self.r)
        cn = arb_mat([[arb(p[i, 0].mid())] for i in range(p.nrows())])
        self.r = (Qi*M)*self.r + Qi*(p - cn)
        self.c = cn; self.B = Qm

    def dump(self):
        n = self.c.nrows()
        return dict(c=[ser(self.c[i, 0]) for i in range(n)], B=[[ser(self.B[i, j]) for j in range(n)] for i in range(n)],
                    r=[ser(self.r[i, 0]) for i in range(n)])

    @staticmethod
    def load(d):
        o = Lohner.__new__(Lohner)
        n = len(d['c'])
        o.c = arb_mat([[des(t)] for t in d['c']]); o.r = arb_mat([[des(t)] for t in d['r']])
        o.B = arb_mat([[des(d['B'][i][j]) for j in range(n)] for i in range(n)])
        return o


def substeps(tb, L, Ftape, T4):
    """generator over engine substeps: (k, kind, ys start ball, hs, Rc, x0 (x-steps)) replicating _tube_setup nsub=2"""
    KL = L.KL
    x_sw = de(tb['X_SWITCH'])
    xpos = None
    k = 0
    for j, st in enumerate(tb['steps']):
        kind = st['kind']; h = de(st['h'])
        c = [de(p) for p in st['c']]; setrad = de(st['setrad'])
        ncomp = 4 if kind == 'tau' else 3
        field = T4 if kind == 'tau' else Ftape
        y0b = [c[i] + sym(setrad*arb('1.01')) for i in range(ncomp)]
        Rc = abs(h)/LS2.Q_SUB
        if kind == 'x' and xpos is None:
            xpos = x_sw
        y1, Bx, Yc2 = TY.step_cauchy2(field, y0b, h, KL + 1, q=abs(h)/Rc, conv=lambda q_: _cc(q_, arb(0)))
        Yi = [[Yc2[i][n] for n in range(KL + 2)] for i in range(ncomp)]
        totrad = [Bx[i].rad() for i in range(ncomp)]
        for s in range(2):
            ts = h*s/2; hs = h*(s + 1)/2 - ts
            if s == 0:
                ys = y0b
            else:
                tq = abs(ts)/Rc
                ys = [Q.horner(Yi[i], ts) + sym(totrad[i]*tq**(KL + 2)/(1 - tq)) for i in range(ncomp)]
            yield k, kind, field, ys, hs, Rc, (xpos + ts if kind == 'x' else None)
            k += 1
        if kind == 'x':
            xpos = xpos + h


def box_entries(kind, yb, xbox, xpb):
    """step-form extras entries at one complex box (values), plus D_t and trace at the box"""
    loc = Q.ode_xseries(yb[:3], 7)
    xs = [xbox, acb(1)] + [acb(0)]*5
    ex = s_exp(xs, 7)
    cb = C.generic_columns(loc[0], loc[1], loc[2], [acb(1)] + [acb(0)]*6, ex, 7)
    Eb = C.x_form_matrix_entries(cb, 1, lambda num, d: num[0]/d[0])
    out = {}
    for key, e in Eb.items():
        if e is None: continue
        v = e if not isinstance(e, list) else e[0]
        out[key] = xpb*v
    return out, cb['Dt'][0], cb['trace'][0]


def step_data(L, kind, field, ys, hs, Rc, x0, st, want_series=True):
    KL = L.KL
    ncomp = len(ys)
    Kpre = 30
    y1, Bx, Yc2 = TY.step_cauchy2(field, ys, hs, Kpre + 6, q=abs(hs)/Rc, conv=lambda q_: _cc(q_, arb(0)))
    Yp = [[Yc2[i][n] for n in range(Kpre + 7)] for i in range(ncomp)]
    totrad = [Bx[i].rad() for i in range(ncomp)]
    rho = st['rho']
    # --- disc sup of the extras (engine disc, NCELL x NCELL cells)
    m_ = len(Yp[0]); r_ = rho/Rc
    tailY = [totrad[i]*r_**m_/(1 - r_) for i in range(ncomp)]
    Ypc = [[acb(a) for a in Yp[i]] for i in range(ncomp)]
    hc = rho/NCELL
    sup = {}; dtmax = arb(0); trmax = arb(0); dt_ok = True
    for ia in range(NCELL):
        for ib in range(NCELL):
            tcell = acb(-rho + (2*ia + 1)*hc, -rho + (2*ib + 1)*hc) + csym(hc*arb('1.415'))
            yb = [Q.horner(Ypc[i], tcell) + csym(tailY[i]) for i in range(ncomp)]
            if kind == 'tau':
                xbox = yb[3]
                xpb = field.eval(yb, conv=lambda cc: acb(sym_const(cc)))[3]
            else:
                xbox = acb(x0) + tcell; xpb = acb(1)
            vals, dt, tr = box_entries(kind, yb, xbox, xpb)
            for key, v in vals.items():
                sup[key] = sup.get(key, arb(0)).max(abs(v).upper())
            dtmax = dtmax.max(abs(dt).upper()); trmax = trmax.max(abs(tr).upper())
            dt_ok = dt_ok and dt.real.contains(0)
    return dict(Yp=Yp, totrad=totrad, sup=sup, dtmax=dtmax, trmax=trmax, dt_ok=dt_ok)


def jets_tight(field, y0, K):
    """Taylor coefficients 0..K of the ODE solution through every point of the ball y0, without the wrapping of a
    ball recursion: y_n(y0) in y_n(mid) + sum_j [d y_n / d y0_j](ball) [-r_j, r_j]  (mean value theorem; the
    derivative jets are Dual numbers over the ball)."""
    from core import Dual
    d = len(y0)
    c = [arb(v.mid()) for v in y0]
    Yc = TY.jets(field, c, K, lambda q_: _cc(q_, arb(0)))
    yd = [Dual(y0[i], [arb(1) if j == i else arb(0) for j in range(d)]) for i in range(d)]
    Yd = TY.jets(field, yd, K, lambda q_: _cc(q_, yd[0]))
    rads = [v.rad() for v in y0]
    out = []
    for i in range(d):
        row = []
        for n in range(K + 1):
            v = Yc[i][n]
            if n > 0:
                for j in range(d):
                    v = v + Yd[i][n].d[j]*sym(rads[j])
            else:
                v = y0[i]
            row.append(v)
        out.append(row)
    return out


MV_TRIG = 1e-16
MVCOUNT = [0]


def bach_mv(field, y0, n_in, kind, x0, bt0):
    """mean-value form of the Bach series (true and N-c variant) over the start ball y0:
    b_n(y0) in b_n(mid) + sum_j [d b_n / d y0_j](ball) [-r_j, r_j];  A, A', l' kept from the ball run."""
    from core import Dual
    d = len(y0)
    c = [arb(v.mid()) for v in y0]
    Yc = TY.jets(field, c, n_in, lambda q_: _cc(q_, arb(0)))
    yd = [Dual(y0[i], [arb(1) if j == i else arb(0) for j in range(d)]) for i in range(d)]
    Yd = TY.jets(field, yd, n_in, lambda q_: _cc(q_, yd[0]))
    rads = [v.rad() for v in y0]
    z = arb(0)

    def xpser(Y):
        if kind == 'tau':
            return s_deriv(Y[3])[:n_in]
        zz = 0*Y[0][0]
        return [zz + 1] + [zz]*(n_in - 1)
    out = []
    for omf in (None, C.DELTA_NC):
        bm = Q.bach_from_series(Yc[0][:n_in], Yc[1][:n_in], Yc[2][:n_in], xpser(Yc), n_in, om_fac=omf)
        bd = Q.bach_from_series(Yd[0][:n_in], Yd[1][:n_in], Yd[2][:n_in], xpser(Yd), n_in, om_fac=omf)
        bb = []
        for cc in range(4):
            row = []
            for k_ in range(len(bm['b'][cc])):
                v = bm['b'][cc][k_]
                for j in range(d):
                    v = v + bd['b'][cc][k_].d[j]*sym(rads[j])
                row.append(v)
            bb.append(row)
        bm2 = dict(bm); bm2['b'] = bb
        # A, A1, l1 from the ball run (no derivative amplification beyond one order)
        bm2['A'] = bt0['A']; bm2['A1'] = bt0['A1']; bm2['l1'] = bt0['l1']
        out.append(bm2)
    return out


def series_entries(L, kind, field, ys, hs, Rc, x0, Ks):
    """extras entries of the step-form augmented matrix as series of length Ks+1"""
    n_in = Ks + 5
    ncomp = len(ys)
    Ys = jets_tight(field, ys, n_in)
    z = arb(0)
    if kind == 'tau':
        xs = Ys[3][:n_in]; xp = s_deriv(Ys[3])[:n_in]
    else:
        xs = [x0, arb(1)] + [z]*(n_in - 2); xp = [arb(1)] + [z]*(n_in - 1)
    ex = s_exp(xs, n_in)
    bo = None
    bt0 = Q.bach_from_series(Ys[0][:n_in], Ys[1][:n_in], Ys[2][:n_in], xp, n_in)
    if max(float(bt0['b'][c][0].rad()) for c in range(4)) > MV_TRIG:
        bo = bach_mv(field, ys, n_in, kind, x0, bt0)
        MVCOUNT[0] += 1
    cols = C.generic_columns(Ys[0][:n_in], Ys[1][:n_in], Ys[2][:n_in], xp, ex, n_in, bach_override=bo)
    n = cols['n']
    Ex = C.x_form_matrix_entries(cols, n, lambda num, d: s_div(num, d, n))
    E = {key: (s_mul(xp, e, n) if kind == 'tau' else e) for key, e in Ex.items() if e is not None}
    return E, cols, Ys


def main(k0, k1, probe=False):
    old = ctx.prec
    try:
        L = QB.engine_b(log=lambda *a: None)
        ctx.prec = 128
        tb = pickle.load(open(QB.NEW_TUBE, 'rb'))
        import pipeline as PL, driver_v2 as V2
        Ftape = Tape([PL.load_expr(s) for s in PL.FIELDS['f']], [Q.Nn, Q.omn, Q.Vn], {sp.Symbol('k'): sp.Rational(1, 3)})
        T4 = V2.tau_tape(sp.Rational(1, 3))
        ck = HERE + 'pass_ckpt.json'
        if k0 == 0:
            stg = json.load(open(HERE + 'stages.json'))
            vec = {nm: Lohner([des(t) for t in stg['sonic'][nm]['val']]) for nm in VNAMES}
            RB = dict(active=False)
            extra = dict(N7=dict(cells=[]), checks={}, max={'rem': '0', 'dt': '0', 'tr': '0', 'Ks': 0, 'aaug': '0'}, dt_all_ok=True)
        else:
            d = json.load(open(ck)); assert d['k'] == k0, (d['k'], k0)
            vec = {nm: Lohner.load(d['vec'][nm]) for nm in VNAMES}
            RB = d['RB']; extra = d['extra']
        if RB.get('active'):
            RB['G'] = arb_mat([[des(t) for t in r] for r in RB['G']]); RB['S'] = arb_mat([[des(t)] for t in RB['S']])
        fl = open(HERE + 'pass_steps.jsonl', 'a')
        xV = des(extra['N7']['xV']) if 'xV' in extra['N7'] else None
        for (k, kind, field, ys, hs, Rc, x0) in substeps(tb, L, Ftape, T4):
            if k < k0:
                continue
            if k >= k1:
                break
            t1 = time.time()
            st = L.steps[k]
            assert st['h'].overlaps(hs) and st['kind'] == kind, ('substep mismatch', k)
            sd = step_data(L, kind, field, ys, hs, Rc, x0, st)
            # tight sups on the transport disc rho_T = rho/2: Taylor part (order KSER) + Cauchy tail from the crude
            # cell sup on the engine disc rho:  |F(t)| <= sum_{n<=K} |F_n| rho_T^n + M_rho q^{K+1}/(1-q), q = 1/2
            rhoT = st['rho']/2
            stT = dict(st); stT['rho'] = rhoT
            KSER = 50
            E, cols, Ys = series_entries(L, kind, field, ys, hs, Rc, x0, KSER)
            qT = arb(1)/2
            sup = {}
            for key, ser_ in E.items():
                acc = arb(0); pw = arb(1)
                for nn in range(KSER + 1):
                    acc += ser_[nn].abs_upper()*pw; pw = pw*rhoT
                sup[key] = acc + sd['sup'].get(key, arb(0))*qT**(KSER + 1)/(1 - qT)
            # N2 on this step: |D_t| on the real step <= Taylor part + Cauchy tail (crude disc sup)
            dts = cols['Dt']
            acc = arb(0); pw = arb(1)
            for nn in range(len(dts)):
                acc += dts[nn].abs_upper()*pw; pw = pw*abs(hs)
            qD = abs(hs)/st['rho']
            sd['dtmax'] = acc + sd['dtmax']*qD**len(dts)/(1 - qD)
            sd['dt_ok'] = all(x.contains(0) for x in dts)
            lam = [arb(1)]*NA
            mP = max([float(sup.get((i, IP), arb(0))) for i in range(4)] + [1e-300])
            lam[IP] = C.pow2_le(mP)
            for j in range(6, NA):
                m = max([float(sup[(i, jj)]/lam[i]) for (i, jj) in sup if jj == j] + [1e-300])
                lam[j] = C.pow2_le(m)
            a_hom = st['a0'] + KAP*st['a1']
            rows = {}
            for (i, j), s_ in sup.items():
                rows[i] = rows.get(i, arb(0)) + s_*lam[j]/lam[i]
            a_aug = a_hom + max(rows.get(i, arb(0)) for i in range(4))
            for i in (IJ, IP):
                a_aug = a_aug.max(rows.get(i, arb(0)))
            # step order: smallest K in 12..KSER with the optimal-radius remainder below TOL_A (else KSER)
            af = float(a_aug.upper()); hf = float(abs(hs).upper()); rfT = float(rhoT.lower())
            Ks = KSER
            for Kt in range(12, KSER + 1):
                if LS2.log_rem_opt(af, hf, rfT, Kt) < math.log(TOL_A):
                    Ks = Kt; break
            rem = LS2.rem_opt(a_aug, hs, rhoT, Ks)
            Kser = KSER
            # augmented scaled Taylor matrices
            At = []
            for nn in range(Ks + 1):
                M = arb_mat(NA, NA)
                Ah = st['A0'][nn] + KAP*st['A1'][nn]
                for i in range(4):
                    for j in range(4):
                        M[i, j] = Ah[i, j].real
                for (i, j), s_ in E.items():
                    M[i, j] = s_[nn]*lam[j]/lam[i]
                At.append(M)
            Phi = [arb_mat(NA, NA)]
            for i in range(NA): Phi[0][i, i] = 1
            for nn in range(Ks):
                s_ = arb_mat(NA, NA)
                for m in range(nn + 1):
                    s_ += At[m]*Phi[nn - m]
                Phi.append(s_*(arb(1)/(nn + 1)))

            def Pmat(t, remv):
                P = arb_mat(NA, NA)
                for nn in range(Ks, -1, -1):
                    P = P*t + Phi[nn]
                for i in range(NA):
                    for j in range(NA):
                        P[i, j] += sym(remv)*lam[i]/lam[j]
                        P[i, j] = P[i, j]
                # unscale: P_hat = D P~ D^-1  (entries times lam_i / lam_j); remainder already added in scaled units
                U_ = arb_mat(NA, NA)
                for i in range(NA):
                    for j in range(NA):
                        U_[i, j] = P[i, j]*lam[i]/lam[j]
                return U_

            def Pscaled(t, remv):
                P = arb_mat(NA, NA)
                for nn in range(Ks, -1, -1):
                    P = P*t + Phi[nn]
                for i in range(NA):
                    for j in range(NA):
                        P[i, j] += sym(remv)
                U_ = arb_mat(NA, NA)
                for i in range(NA):
                    for j in range(NA):
                        U_[i, j] = P[i, j]*lam[i]/lam[j]
                return U_
            Ph = Pscaled(hs, rem)
            # ---- N7: V on U (x-steps only)
            if kind == 'x':
                xe = x0 + hs
                if xe < U_HI and x0 > U_LO:
                    lo = xe.max(U_LO); hi = x0.min(U_HI)
                    KL_ = len(Ys[2]) - 1
                    Vs = Ys[2]; dV = s_deriv(Vs)
                    tI = (lo - x0).union(hi - x0)
                    qq = abs(hs)/Rc
                    tail = sd['totrad'][2]*qq**(KL_ + 1)/(1 - qq)
                    dtail = sd['totrad'][2]/Rc*(KL_ + 1)*qq**KL_/(1 - qq)**2
                    Vp = Q.horner(dV, tI) + sym(dtail)
                    Vlo = Q.horner(Vs, lo - x0) + sym(tail); Vhi = Q.horner(Vs, hi - x0) + sym(tail)
                    cell = dict(k=k, lo=lo.str(12), hi=hi.str(12), Vprime_pos=bool(Vp > 0), Vlo=Vlo.str(6), Vhi=Vhi.str(6),
                                Vprime=Vp.str(5))
                    if Vlo < 0 and Vhi > 0:
                        a_, b_ = lo, hi
                        for _ in range(110):
                            mid = arb(((a_ + b_)/2).mid())
                            vm = Q.horner(Vs, mid - x0) + sym(tail)
                            if vm < 0: a_ = mid
                            elif vm > 0: b_ = mid
                            else: break
                        xV = a_.union(b_)
                        extra['N7']['xV'] = ser(xV); extra['N7']['k'] = k
                        cell['zero'] = xV.str(25)
                    elif not (Vlo > 0 or Vhi < 0):
                        cell['undecided'] = True
                    extra['N7']['cells'].append(cell)
            # ---- check points inside this substep (x-steps)
            pts = {}
            if kind == 'x':
                for nm, xc_ in list(CHECK_X.items()) + ([('xV', xV)] if xV is not None else []):
                    if xc_ is None or nm in extra['checks']: continue
                    tt = xc_ - x0
                    if tt <= 0 and tt >= hs:
                        r2 = LS2.rem_opt(a_aug, tt, rhoT, Ks)
                        Pt = Pscaled(tt, r2)
                        pts[nm] = (Pt, tt)
            for nm, (Pt, tt) in pts.items():
                rec = {}
                for vn in VNAMES:
                    v = vec[vn].value()
                    w = Pt*arb_mat([[x] for x in v])
                    rec[vn] = [ser(w[i, 0]) for i in range(NA)]
                stv = [Q.horner(Ys[i], tt) + sym(sd['totrad'][i]*(abs(tt)/Rc)**len(Ys[i])/(1 - abs(tt)/Rc)) for i in range(3)]
                A_ = Q.T_ACONS.eval(stv)[0]
                rec['state'] = [ser(x) for x in stv]; rec['A'] = ser(A_)
                rec['x'] = ser(x0 + tt)
                extra['checks'][nm] = rec
                if nm == 'xV':
                    RB['active'] = True
                    RB['kV'] = k
                    RB['tV'] = ser(tt)
            # ---- route B (variation of constants + adjoint, hom 4x4 block, real column F_R)
            if RB.get('active'):
                Kb = Kser
                Ah = [real_mat(st['A0'][nn] + KAP*st['A1'][nn]) for nn in range(Kb + 1)]
                ER = E
                FR = [[ER[(i, 6)][nn] for i in range(4)] for nn in range(Kb + 1)]
                I4 = arb_mat(4, 4)
                for i in range(4): I4[i, i] = 1
                Psi = [I4]
                for nn in range(Kb):
                    s_ = arb_mat(4, 4)
                    for m in range(nn + 1):
                        s_ -= Psi[nn - m]*Ah[m]
                    Psi.append(s_*(arb(1)/(nn + 1)))
                Fv = [arb_mat([[FR[nn][i]] for i in range(4)]) for nn in range(Kb + 1)]
                G = []
                for nn in range(Kb + 1):
                    acc = arb_mat(4, 1)
                    for m in range(nn + 1):
                        acc += Psi[m]*Fv[nn - m]
                    G.append(acc)
                a4 = 4*a_hom
                Fsup = max(sup.get((i, 6), arb(0)) for i in range(4))
                af = float(a4.upper()); hf = float(abs(hs).upper()); rf = float(rhoT.lower())

                def remB(tabs):
                    tf = float(arb(tabs).upper())
                    rp = min(rf, max((Kb + 1)/af, 1.05*max(tf, hf)))
                    rp = arb(repr(rp))
                    qv = arb(tabs)/rp
                    e_ = (a4*rp).exp()*qv**(Kb + 1)/(1 - qv)
                    return e_, e_*Fsup*arb(tabs)

                def psi_at(t):
                    P = arb_mat(4, 4)
                    for nn in range(Kb, -1, -1): P = P*t + Psi[nn]
                    e_, _ = remB(abs(t))
                    for i in range(4):
                        for j in range(4): P[i, j] += sym(e_)
                    return P

                def wint(t):
                    w = arb_mat(4, 1)
                    for nn in range(Kb, -1, -1):
                        w = w*t + G[nn]*(arb(1)/(nn + 1))
                    w = w*t
                    _, e2 = remB(abs(t))
                    for i in range(4): w[i, 0] += sym(e2)
                    return w
                if RB.get('kV') == k:
                    tV = des(RB['tV'])
                    RB['psi_h_V'] = None
                    RB['Vstep'] = dict(psiH=[[ser(x) for x in r] for r in mlist(psi_at(hs))],
                                       wH=[ser(x) for x in [wint(hs)[i, 0] for i in range(4)]],
                                       wV=[ser(x) for x in [wint(tV)[i, 0] for i in range(4)]])
                    # forward Phi(tV) of the hom block
                    Phif = [I4]
                    for nn in range(Kb):
                        s_ = arb_mat(4, 4)
                        for m in range(nn + 1): s_ += Ah[m]*Phif[nn - m]
                        Phif.append(s_*(arb(1)/(nn + 1)))
                    P = arb_mat(4, 4)
                    for nn in range(Kb, -1, -1): P = P*tV + Phif[nn]
                    e_ = LS2.rem_opt(a_hom, tV, rhoT, Kb)
                    for i in range(4):
                        for j in range(4): P[i, j] += sym(e_)
                    RB['Vstep']['phiV'] = [[ser(x) for x in r] for r in mlist(P)]
                    RB['G'] = I4; RB['S'] = arb_mat(4, 1)
                else:
                    wk = wint(hs)
                    RB['S'] = RB['S'] + RB['G']*wk
                    RB['G'] = RB['G']*psi_at(hs)
            # ---- transport every vector
            for vn in VNAMES:
                vec[vn].step(Ph)
            mx = extra['max']
            mx['rem'] = str(max(float(mx['rem']), float(rem.upper())))
            mx['dt'] = str(max(float(mx['dt']), float(sd['dtmax'])))
            mx['tr'] = str(max(float(mx['tr']), float(sd['trmax'])))
            mx['Ks'] = max(mx['Ks'], Ks); mx['aaug'] = str(max(float(mx['aaug']), float(a_aug.upper())))
            extra['dt_all_ok'] = extra['dt_all_ok'] and sd['dt_ok']
            fl.write(json.dumps(dict(k=k, kind=kind, Ks=Ks, a=a_aug.str(4), rem=rem.str(3), dt=sd['dtmax'].str(3),
                                     sec=round(time.time() - t1, 2), Rwidth=max(float(x.rad()) for x in vec['R'].value()[:4]))) + '\n')
            fl.flush()
            if k % 20 == 0 or probe:
                log('k=%d %s Ks=%d a=%s rem=%s dt=%s %.2fs  R[0]=%s' % (k, kind, Ks, a_aug.str(3), rem.str(3), sd['dtmax'].str(3),
                                                                     time.time() - t1, vec['R'].value()[0].str(10)))
            if k == len(L.steps) - 1:
                # end state (x_m)
                xe_ = Ys[3][0] if kind == 'tau' else x0 + hs
                ste = [Q.horner(Ys[i], hs) + sym(sd['totrad'][i]*(abs(hs)/Rc)**len(Ys[i])/(1 - abs(hs)/Rc)) for i in range(3)]
                extra['end'] = dict(x=ser(x0 + hs), state=[ser(x) for x in ste])
        knext = min(k1, len(L.steps))
        RBd = dict(RB)
        if RB.get('active') and 'G' in RB and not isinstance(RB['G'], list):
            RBd['G'] = [[ser(x) for x in r] for r in mlist(RB["G"])]
            RBd['S'] = [ser(RB['S'][i, 0]) for i in range(4)]
        json.dump(dict(k=knext, vec={nm: vec[nm].dump() for nm in VNAMES}, RB=RBd, extra=extra), open(ck + '.tmp', 'w'))
        os.replace(ck + '.tmp', ck)
        log('checkpoint at k=%d' % knext)
        return 3 if knext < len(L.steps) else 0
    finally:
        ctx.prec = old


if __name__ == '__main__':
    k0, k1 = int(sys.argv[1]), int(sys.argv[2])
    rc = main(k0, k1, probe=len(sys.argv) > 3)
    sys.exit(rc)
